internal static class ClientPositionVerification {
    static void Check(bool value,string message){if(!value)throw new Exception(message);}
    static readonly byte[] Key=CreateKey();static byte[] CreateKey(){var key=new byte[214];for(int i=0;i<key.Length;i++)key[i]=(byte)i;return key;}
    static byte[] Wrap(byte[] body){var b=new List<byte>();uint length=(uint)body.Length+4;while(length>=128){b.Add((byte)((length&127)|128));length>>=7;}b.Add((byte)length);b.AddRange(body);return b.ToArray();}
    static byte[] Handshake(){var bytes=new byte[283];var prefix=new byte[]{0x10,0x36,0x8c,2,0x30,0x82,1,8,2,0x82,1,1,0};Buffer.BlockCopy(prefix,0,bytes,0,prefix.Length);return bytes;}
    static byte[] Move(float x,float y=200,float z=300,bool stop=true){var b=new List<byte>{1,0x37,stop?(byte)0:(byte)2};b.AddRange(BitConverter.GetBytes(x));b.AddRange(BitConverter.GetBytes(y));b.AddRange(BitConverter.GetBytes(z));b.AddRange(new byte[6]);if(!stop)b.Add(1);b.AddRange(BitConverter.GetBytes(1792079020000L));return b.ToArray();}
    static byte[] Combine(params byte[][] chunks){var b=new List<byte>();foreach(var part in chunks)b.AddRange(part);return b.ToArray();}
    static Segment Segment(uint seq,byte[] data,int port=50000){return new Segment{Src="127.0.0.1",Dst="127.0.0.2",SrcPort=port,DstPort=13328,Seq=seq,Data=data};}
    static string Server(int port=50000){return "127.0.0.2:13328>127.0.0.1:"+port;}
    static byte[] Session(PositionRc4 cipher,params byte[][] movements){var frames=new List<byte[]>();frames.Add(Wrap(Handshake()));var setup=new byte[158];setup[0]=0x13;setup[1]=0x36;frames.Add(Wrap(cipher.Transform(setup)));foreach(var body in movements)frames.Add(Wrap(cipher.Transform(body)));return Combine(frames.ToArray());}
    internal static void Run(string root){
        using(var cipher=new PositionRc4(Encoding.ASCII.GetBytes("Key"))){var result=cipher.Transform(Encoding.ASCII.GetBytes("Plaintext"));Check(BitConverter.ToString(result).Replace("-","")=="BBF316E8D940AF0AD3","Published RC4 vector");}
        EnemyDetailReader.Position position;bool stationary;var move=Move(100);Check(ClientMovement.Parse(move,10,out position,out stationary)&&position.X==100&&stationary,"Idle position layout");Check(ClientMovement.Parse(Move(100,200,300,false),10,out position,out stationary)&&!stationary,"Moving position layout");Check(!ClientMovement.Parse(Move(float.NaN),10,out position,out stationary),"NaN rejected");for(int n=0;n<move.Length;n++){var cut=new byte[n];Buffer.BlockCopy(move,0,cut,0,n);Check(!ClientMovement.Parse(cut,10,out position,out stationary),"Truncated position rejected");}
        int lookups=0;using(var reader=new ClientPositionReader(delegate(int pid){lookups++;return (byte[])Key.Clone();},false))using(var cipher=new PositionRc4(Key)){
            var bytes=Session(cipher,Move(100));reader.Consume(Segment(1000,bytes),10,42);reader.Maintain();Check(lookups==0&&reader.Read(Server(),10)==null,"Disabled option cannot capture, scan memory or retain a position");reader.Configure(true);
            // Out-of-order pieces, overlap, and a retransmission still consume cipher bytes once.
            var first=new byte[100];Buffer.BlockCopy(bytes,0,first,0,100);var tail=new byte[bytes.Length-180];Buffer.BlockCopy(bytes,180,tail,0,tail.Length);var middle=new byte[80];Buffer.BlockCopy(bytes,100,middle,0,80);
            reader.Consume(Segment(1000,first),10,42);reader.Consume(Segment(1180,tail),10,42);reader.Consume(Segment(1100,middle),10,42);reader.Maintain();var reading=reader.Read(Server(),10);Check(lookups==1&&reading!=null&&reading.Position.X==100,"Fresh handshake and matching in-memory session key decode ordered movement");reader.Consume(Segment(1000,bytes),10.1,42);Check(reader.Read(Server(),10.1).Position.X==100,"Retransmissions cannot advance RC4 twice");Check(reader.Read(Server(50001),10)==null,"Own position cannot leak into another flow");
            uint next=(uint)(1000+bytes.Length);var clock=Wrap(cipher.Transform(new byte[]{1,0x36,0,0,0,0,0,0,0,0}));reader.Consume(Segment(next,clock),16,42);next+=(uint)clock.Length;Check(reader.Read(Server(),16)!=null,"Confirmed stop remains valid while the exact stream is live");Check(reader.Read(Server(),27)==null,"No traffic cannot freeze an old exact distance indefinitely");
            var walk=Wrap(cipher.Transform(Move(150,200,300,false)));reader.Consume(Segment(next,walk),17,42);Check(reader.Read(Server(),17).Position.X==150&&reader.Read(Server(),20)==null,"Walking updates position; a missing moving update cannot look stationary");reader.Reset();Check(reader.Read(Server(),17)==null,"Capture reset removes positions and cipher state");reader.Configure(false);reader.Maintain();Check(lookups==1&&!reader.Enabled,"Disable stops all key lookups");
        }
        using(var stream=new ClientPositionStream(Server(),42))using(var cipher=new PositionRc4(Key)){var bytes=Session(cipher,Move(93400));stream.Consume(Segment(uint.MaxValue-100,bytes),10);var wrong=(byte[])Key.Clone();Array.Reverse(wrong);Check(!stream.AcceptsKey(wrong)&&stream.AcceptsKey(Key)&&stream.Frames==0,"Candidate verification checks the pending handshake without advancing RC4");Check(!stream.OfferKey(wrong)&&stream.Latest==null,"Wrong session key cannot emit a position");Check(stream.OfferKey(Key)&&stream.Read(10).Position.X==93400,"Correct key after wrong candidate and TCP wrap");}
        using(var stream=new ClientPositionStream(Server(),42)){stream.Consume(Segment(1,new byte[]{1}),10);for(uint i=0;i<66;i++)stream.Consume(Segment(1000+i*100,new byte[20]),10);Check(stream.Failed&&stream.Read(10)==null,"Bounded missing TCP data fails closed");}
        VerifyEnemyBridge();VerifyAdaptiveLookup();VerifyNewSessionRetry();VerifyActiveSessionKey();
        int premature=0;using(var reader=new ClientPositionReader(delegate(int pid){premature++;return (byte[])Key.Clone();},false)){reader.Configure(true);reader.Consume(Segment(1,Wrap(Handshake())),10,42);reader.Maintain();Check(premature==0,"RSA handshake alone cannot trigger a search before there is encrypted setup to validate");}
        double activity=100;int staleLookups=0;using(var reader=new ClientPositionReader(delegate(int pid){staleLookups++;if(pid==42)throw new InvalidOperationException("Old process is no longer available");return (byte[])Key.Clone();},false,delegate{return activity;}))using(var oldCipher=new PositionRc4(Key))using(var liveCipher=new PositionRc4(Key)){
            reader.Configure(true);reader.Consume(Segment(1,Session(oldCipher,Move(100))),10,42);reader.Maintain();Check(staleLookups==1,"Initial process failure captured");activity=131;reader.Consume(Segment(1,Session(liveCipher,Move(200)),50001),11,43);reader.Maintain();Check(reader.Read(Server(50001),11)!=null&&reader.ReadingStatus=="Exact distance ready","New active session is not hidden by a previous process error");activity=134;reader.Maintain();Check(staleLookups==2,"Inactive old connection does not trigger more memory scans while the new one is ready");
        }
        using(var entered=new ManualResetEvent(false))using(var release=new ManualResetEvent(false))using(var reader=new ClientPositionReader(delegate(int pid){entered.Set();release.WaitOne(2000);return (byte[])Key.Clone();},false))using(var cipher=new PositionRc4(Key)){
            reader.Configure(true);reader.Consume(Segment(1000,Session(cipher,Move(100))),10,42);var worker=new Thread(reader.Maintain);worker.Start();Check(entered.WaitOne(2000),"Lookup test entered");reader.Configure(false);release.Set();Check(worker.Join(2000)&&reader.Read(Server(),10)==null,"Disable during a lookup cannot resurrect a key or stale position");
        }
        var detail=new EnemyDetailOptions();Check(!detail.ExactPosition,"Exact mode is opt-in");detail.ExactPosition=true;var copy=detail.Copy();copy.ExactPosition=false;Check(detail.ExactPosition&&!copy.ExactPosition,"Independent option snapshots");var options=new EnemyHealthOptions();options.Details.ExactPosition=true;var json=new JavaScriptSerializer();var restored=EnemyHealthOptions.Read(json.Deserialize<Dictionary<string,object>>(json.Serialize(new{enemyHealth=options})));Check(restored.Details.ExactPosition&&!EnemyHealthOptions.TargetDefaults().Details.ExactPosition,"Exact mode persistence and main-only defaults");
        using(var license=typeof(ClientPositionReader).Assembly.GetManifestResourceStream("Aion2ProtocolResearchLicense.txt"))Check(license!=null,"Distributed implementation retains embedded MIT notice");
        File.WriteAllText(Path.Combine(root,"client-position-test.txt"),"PASS: optional mode defaults off; no memory calls when disabled; adaptive lookup outside the former arena, bounded/resumed chunks without rereading the prefix; one-allocation reacquisition validated by a new handshake; stale cached session rejection; new setup bypasses old retry delay; obsolete concurrent lookup cannot overwrite the new session; cache revalidation, invalid permutation and cancellation; RC4 standard vector; fragmented/retransmitted/out-of-order and wrapped TCP; per-flow session isolation; wrong-key rejection; bounded gaps; real movement/stop semantics and traffic freshness; reset; disable during asynchronous lookup; option copy/persistence; retained embedded MIT notice. Tests use synthetic keys and never open game memory.");
    }
    static byte[] StateHeader(long table,long keyPointer,bool valid=true){var bytes=new byte[0x124];Buffer.BlockCopy(BitConverter.GetBytes(table),0,bytes,0,8);Buffer.BlockCopy(BitConverter.GetBytes(keyPointer),0,bytes,0x10,8);Buffer.BlockCopy(BitConverter.GetBytes(214),0,bytes,0x18,4);for(int i=0;i<256;i++)bytes[0x24+i]=(byte)i;if(!valid)bytes[0x24]=bytes[0x25];return bytes;}
    static void VerifyNewSessionRetry(){
        double now=100;int searches=0;using(var reader=new ClientPositionReader(delegate(int pid){searches++;return searches==1?null:(byte[])Key.Clone();},false,delegate{return now;}))using(var first=new PositionRc4(Key))using(var next=new PositionRc4(Key)){
            reader.Configure(true);reader.Consume(Segment(1,Session(first,Move(100))),100,42);reader.Maintain();Check(searches==1&&reader.Read(Server(),100)==null,"Failed lookup leaves first session unavailable");
            now=101;reader.Consume(Segment(1,Session(next,Move(200)),50001),101,42);reader.Maintain();Check(searches==2&&reader.Read(Server(50001),101)!=null,"New encrypted setup does not inherit a previous session's thirty-second retry delay");
        }
        using(var entered=new ManualResetEvent(false))using(var release=new ManualResetEvent(false)){
            now=100;searches=0;using(var reader=new ClientPositionReader(delegate(int pid){if(++searches==1){entered.Set();release.WaitOne(2000);throw new InvalidOperationException("Obsolete session closed");}return (byte[])Key.Clone();},false,delegate{return now;}))using(var first=new PositionRc4(Key))using(var next=new PositionRc4(Key)){
                reader.Configure(true);reader.Consume(Segment(1,Session(first,Move(100))),100,42);var worker=new Thread(reader.Maintain);worker.Start();Check(entered.WaitOne(2000),"Previous session lookup entered");
                now=101;reader.Consume(Segment(1,Session(next,Move(200)),50001),101,42);release.Set();Check(worker.Join(2000),"Previous lookup exits after a session change");reader.Maintain();
                Check(searches==2&&reader.Read(Server(50001),101)!=null,"Completion of an obsolete lookup cannot restore its retry delay over a newer setup");
            }
        }
    }
    static void VerifyActiveSessionKey(){
        const long table=0x70000000,oldPointer=0x71000000,nextPointer=0x72000000;var nextKey=(byte[])Key.Clone();for(int i=0;i<nextKey.Length;i++)nextKey[i]^=85;
        Func<long,int,byte[]> read=delegate(long address,int size){if(size==65536&&address==65536){var block=new byte[65536];Buffer.BlockCopy(BitConverter.GetBytes(table),0,block,256,8);Buffer.BlockCopy(BitConverter.GetBytes(table),0,block,512,8);return block;}if(size==0x124){if(address==65792)return StateHeader(table,oldPointer);if(address==66048)return StateHeader(table,nextPointer);}if(size==214){if(address==oldPointer)return (byte[])Key.Clone();if(address==nextPointer)return (byte[])nextKey.Clone();}return null;};
        using(var memory=new SessionKeyMemory(table,read,delegate(long start,long end){var list=new List<SessionKeyMemory.Region>();if(start<=65536&&end>65536)list.Add(new SessionKeyMemory.Region{Base=new IntPtr(65536),Size=new UIntPtr(65536),State=0x1000,Protection=4,Type=0x20000});return list;})){
            byte[] cached=memory.ReadKey(42,delegate{return false;},delegate(byte[] key){return key[0]==Key[0];});Check(cached!=null,"Fixture caches the previous session state");Array.Clear(cached,0,cached.Length);
            double now=100;using(var reader=new ClientPositionReader(null,false,delegate{return now;}))using(var first=new PositionRc4(Key))using(var next=new PositionRc4(nextKey)){
                typeof(ClientPositionReader).GetField("memory",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).SetValue(reader,memory);
                reader.Configure(true);reader.Consume(Segment(1,Session(first,Move(100))),100,42);now=111;reader.Consume(Segment(1,Session(next,Move(200)),50001),111,42);reader.Maintain();
                Check(reader.Read(Server(50001),111)!=null&&reader.Read(Server(50001),111).Position.X==200,"An inactive pending flow cannot validate its cached key instead of the current session");
            }
        }
        Array.Clear(nextKey,0,nextKey.Length);
    }
    static IEnumerable<SessionKeyMemory.Region> SyntheticRegions(long start,long end){for(int i=0;i<2052;i++){long address=0x10000L+i*65536L;if(address<start||address>=end)continue;yield return new SessionKeyMemory.Region{Base=new IntPtr(address),Size=new UIntPtr(65536),State=0x1000,Protection=4,Type=0x20000};}}
    static void VerifyAdaptiveLookup(){
        const long table=0x70000000,keyPointer=0x71000000,wrongPointer=0x72000000,newPointer=0x73000000;long selected=0x10000L+2051*65536L+0x100;var wrong=(byte[])Key.Clone();Array.Reverse(wrong);var nextKey=(byte[])Key.Clone();for(int i=0;i<nextKey.Length;i++)nextKey[i]^=85;int blocks=0,repeated=0;bool invalid=false,relocated=false;var seen=new HashSet<long>();var empty=new byte[65536];
        Func<long,int,byte[]> read=delegate(long address,int size){if(size==65536){blocks++;if(!seen.Add(address))repeated++;if(address==0x10000||address==selected-0x100){var block=new byte[65536];Buffer.BlockCopy(BitConverter.GetBytes(table),0,block,0x100,8);if(relocated&&address==selected-0x100)Buffer.BlockCopy(BitConverter.GetBytes(table),0,block,0x200,8);return block;}return empty;}if(size==0x124){if(address==0x10100)return StateHeader(table,wrongPointer);if(address==selected)return StateHeader(table,keyPointer,!invalid);if(relocated&&address==selected+0x100)return StateHeader(table,newPointer,!invalid);return null;}if(size==214){if(address==keyPointer)return (byte[])Key.Clone();if(address==wrongPointer)return (byte[])wrong.Clone();if(address==newPointer)return (byte[])nextKey.Clone();}return null;};
        using(var cipher=new PositionRc4(Key))using(var stream=new ClientPositionStream(Server(),42))using(var memory=new SessionKeyMemory(table,read,SyntheticRegions)){
            stream.Consume(Segment(1,Session(cipher,Move(1200))),10);byte[] key=null;int attempts=0;while(key==null&&attempts++<12)key=memory.ReadKey(42,delegate{return false;},stream.AcceptsKey);
            Check(key!=null&&attempts>=2&&repeated==0&&blocks==2052,"A state beyond the first 128 MiB is found by resuming, without rereading the prefix or accepting the wrong session");Array.Clear(key,0,key.Length);int before=blocks;key=memory.ReadKey(42,delegate{return false;},stream.AcceptsKey);Check(key!=null&&blocks==before,"Cached session lookup avoids region scans");Array.Clear(key,0,key.Length);
            relocated=true;using(var newCipher=new PositionRc4(nextKey))using(var next=new ClientPositionStream(Server(50001),42)){
                next.Consume(Segment(1,Session(newCipher,Move(1400)),50001),11);before=blocks;key=memory.ReadKey(42,delegate{return false;},next.AcceptsKey);
                Check(key!=null&&blocks==before+1&&next.OfferKey(key)&&next.Read(11).Position.X==1400,"Relocated session state in a previously verified allocation is found with one bounded read and a fresh handshake");Array.Clear(key,0,key.Length);
            }
            invalid=true;key=memory.ReadKey(42,delegate{return false;},stream.AcceptsKey);Check(key==null,"An invalidated state permutation cannot reuse a cached key");
            bool cancelled=false;try{memory.ReadKey(42,delegate{return true;},stream.AcceptsKey);}catch(OperationCanceledException){cancelled=true;}Check(cancelled,"Cancellation interrupts native search before more reads");
        }
        Array.Clear(wrong,0,wrong.Length);Array.Clear(nextKey,0,nextKey.Length);
    }
    static void Var(List<byte> b,uint value){do{byte next=(byte)(value&127);value>>=7;b.Add((byte)(next|(value>0?128:0)));}while(value>0);}
    static void VerifyEnemyBridge(){double now=DpsHistory.UtcNow();using(var reader=new ClientPositionReader(delegate(int pid){return (byte[])Key.Clone();},false))using(var cipher=new PositionRc4(Key)){
        reader.Configure(true);var bytes=Session(cipher,Move(93000,27000,26000));reader.Consume(Segment(1000,bytes),now-20,42);reader.Maintain();uint next=(uint)(1000+bytes.Length);reader.Consume(Segment(next,Wrap(cipher.Transform(new byte[]{1,0x36,0,0,0,0,0,0,0,0}))),now,42);
        var source=new EnemyHealthSignal();source.ClientPositions=reader;source.Configure(true);var own=EnemyTargetVerification.Player(10196,"Charlotta",12202,12202,true);source.Consume(own,0,own.Length,now-8,Server());var npc=new List<byte>{0x41,0x36};Var(npc,345);npc.AddRange(new byte[3]);npc.AddRange(BitConverter.GetBytes(2100146u));npc.AddRange(new byte[2]);foreach(float value in new[]{93400f,27000f,26000f})npc.AddRange(BitConverter.GetBytes(value));npc.AddRange(new byte[7]);Var(npc,119700);Var(npc,119700);npc.AddRange(new byte[52]);var spawn=npc.ToArray();source.Consume(spawn,0,spawn.Length,now,Server());var selection=new List<byte>{0x34,0x38,0,0,0};Var(selection,345);var select=selection.ToArray();source.Consume(select,0,select.Length,now,Server());Check(source.Read()!=null&&source.Read().Distance.HasValue&&Math.Abs(source.Read().Distance.Value-4)<.001,"Main bar uses exact same-flow stationary position beyond the legacy five-second limit");
        var map=new byte[48];map[0]=0x21;map[1]=0x36;reader.ObserveServer(map,0,map.Length,now,Server());Check(!source.Read().Distance.HasValue,"Teleport/load invalidates previous exact position without restarting cipher");
        var placement=new List<byte>{0x23,0x36,0};placement.AddRange(new byte[5]);foreach(float value in new[]{93100f,27000f,26000f})placement.AddRange(BitConverter.GetBytes(value));var placed=placement.ToArray();reader.ObserveServer(placed,0,placed.Length,now,Server());Check(Math.Abs(source.Read().Distance.Value-3)<.001,"Confirmed same-session placement restores exact distance");reader.ObserveServer(map,0,map.Length,now,Server(50001));Check(source.Read().Distance.HasValue,"Other flow load cannot invalidate this enemy distance");reader.Configure(false);Check(!source.Read().Distance.HasValue,"Disabling exact mode does not leave its position behind");
    }}
    internal static void NativeCheck(string root,int pid){var clock=System.Diagnostics.Stopwatch.StartNew();byte[] key=null;Func<byte[],bool> structural=delegate(byte[] bytes){return bytes.Length==214;};try{using(var memory=new SessionKeyMemory()){int chunks=0;do{key=memory.ReadKey(pid,delegate{return clock.Elapsed.TotalSeconds>15;},structural);chunks++;}while(key==null&&memory.SearchPending&&clock.Elapsed.TotalSeconds<15);if(key==null||key.Length!=214)throw new Exception("No supported state found within the bounded lookup");long first=clock.ElapsedMilliseconds;var cached=memory.ReadKey(pid,delegate{return false;},structural);try{if(cached==null||cached.Length!=key.Length)throw new Exception("Cached session lookup failed");for(int i=0;i<key.Length;i++)if(key[i]!=cached[i])throw new Exception("Cached session key changed");File.WriteAllText(Path.Combine(root,"client-position-native-test.txt"),"PASS: bounded read-only native state lookup; first="+first+" ms, cached="+(clock.ElapsedMilliseconds-first)+" ms, chunks="+chunks+". Keys were not persisted. This structural probe does not validate decryption; production requires its actual captured handshake.");}finally{if(cached!=null)Array.Clear(cached,0,cached.Length);}}}finally{if(key!=null)Array.Clear(key,0,key.Length);}}
